import time
import spidev
import signal
import picamera2
from gpiozero import LED
from adafruit_circuitpython.mcp3008 import MCP3008
from paho.mqtt.client import Client, MQTTException

# Constants
SPI_DEVICE = "/dev/spidev0.0"
SPI_SPEED = 50000  # Hz
SPI_MODE = 0b00  # Mode 0 for MCP3002
BIT_RATE = SPI_SPEED * 8  # 8 bits per word
LOADCELL_READING_MIN = 0  # Minimum expected raw value
LOADCELL_READING_MAX = 1023  # Maximum expected raw value

class LoadCellReader:
    def __init__(self, spi_device):
        try:
            self.spi = spidev.SpiDev(spi_device, SPI_MODE)
            self.spi.open(SPI_SPEED)
            self.check_spi_open()
        except (OSError, IOError) as e:
            print(f"Error opening SPI device: {e}")
            raise

    def read_raw_data(self):
        try:
            with self.spi as spi:
                command = [0x01]  # Start conversion command
                response = spi.xfer2([command, 0])  # Send command and receive response
                raw_data = (response[1] & 0x03) << 8 | response[2]
                return raw_data
        except (OSError, IOError) as e:
            print(f"Error reading from SPI: {e}")
            return None

    def convert_to_weight(self, raw_data):
        if raw_data is None:
            return None
        return (raw_data - LOADCELL_READING_MIN) / (LOADCELL_READING_MAX - LOADCELL_READING_MIN) * 2.0  # Convert to kg

    def close(self):
        try:
            self.spi.close()
        except Exception as e:
            print(f"Error closing SPI device: {e}")

    def check_spi_open(self):
        if not self.spi.is_open:
            raise ValueError("SPI device not open")

def signal_handler(signal, frame):
    print("Shutting down...")
    LoadCellReader().close()
    print("SPI device closed.")

def main():
    # Initialize GPIO for LED indicator (optional)
    led = LED(18)  # GPIO 18 as an example
    led.on()

    # Initialize LoadCellReader
    try:
        load_cell_reader = LoadCellReader(SPI_DEVICE)
    except Exception as e:
        print(f"Error initializing LoadCellReader: {e}")
        return

    while True:
        try:
            raw_data = load_cell_reader.read_raw_data()
            if raw_data is None:
                print("Error reading from load cell.")
                continue

            weight = load_cell_reader.convert_to_weight(raw_data)
            print(f"Weight: {weight:.2f} kg")

            # Delay for 0.5 seconds
            time.sleep(0.5)

        except KeyboardInterrupt:
            print("Program terminated by user.")
            signal_handler(signal, frame)  # Install signal handler if not already

        finally:
            load_cell_reader.close()  # Ensure SPI device is closed

if __name__ == "__main__":
    main()

import time
import RPi.GPIO as GPIO
import spidev
import queue
import threading
from gpiozero import DigitalInput
from picamera2 import PiCamera
from adafruit_mcp3008 import MCP3008
from paho.mqtt import client as mqtt

# Constants
DEBOUNCE_TIME = 0.1  # Debounce time in seconds
SAMPLE_RATE_DEFAULT = 1000  # Default sample rate in Hz

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate if sample_rate is not None else SAMPLE_RATE_DEFAULT
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue or queue.Queue()

        self.is_running = False
        self.digital_input = None

        if sensor_type == 'digital':
            self.setup_digital_sensor()
        elif sensor_type == 'analog':
            self.setup_analog_sensor()

    def setup_digital_sensor(self):
        try:
            GPIO.setmode(GPIO.BCM)
            self.digital_input = DigitalInput(self.gpio_pins[self.sensor_id])
        except Exception as e:
            self.log_queue.put("Error setting up digital sensor: {}".format(e))

    def setup_analog_sensor(self):
        try:
            spi = spidev.SpiDev()
            spi.open(0, self.spi_speed)
            self.analog = MCP3008(spi)
            for channel in self.channels:
                self.analog.init_channel(channel)
                self.analog.read_single_channel()
        except Exception as e:
            self.log_queue.put("Error setting up analog sensor: {}".format(e))

    def read_sensor(self):
        if self.sensor_type == 'digital':
            value = self.digital_input.value()
        elif self.sensor_type == 'analog':
            value = self.analog.read_single_channel()
            value = (value * 3.3) / 1024.0  # Convert to volts

        if value >= self.threshold:
            self.log_queue.put(f"Event detected: {self.sensor_id}, Value: {value}")

    def run(self):
        while not self.is_running:
            self.read_sensor()
            time.sleep(DEBOUNCE_TIME)

    def stop(self):
        self.is_running = False
        if self.sensor_type == 'analog':
            spi.close()
        GPIO.cleanup()

    def log(self, message):
        self.log_queue.put(message)

def main():
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"])
    parser.add_argument("--threshold", type=float, default=0.5)
    parser.add_argument("--sample_rate", type=int, default=1000)
    parser.add_argument("--log_file", type=str, default="sound_sensor.log")
    parser.add_argument("--gpio_pins", type=str, nargs="+")
    parser.add_argument("--channels", type=str, nargs="+")
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", type=int, nargs="+")

    args = parser.parse_args()

    sensor_instances = []
    for sensor_id in args.sensor_ids:
        log_queue = queue.Queue()
        sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue)
        sensor.start()
        sensor_instances.append(sensor)

    try:
        while True:
            # Check for KeyboardInterrupt
            if not any(sensor.is_running for sensor in sensor_instances):
                break
    except KeyboardInterrupt:
        for sensor in sensor_instances:
            sensor.stop()

    # Log any final messages
    for sensor in sensor_instances:
        sensor.log("Sensor stopped")

    # Write log messages to file
    with open(args.log_file, 'a') as log_file:
        for message in sensor_instances[0].log_queue.queue:
            log_file.write(f"{message}\n")

if __name__ == "__main__":
    main()

import time
import os
import picamera2
from gpiozero import Button
from face_recognition import FaceRecognizer, load_image_file, encode_image
from paho.mqtt.client import Client, MQTTException
import threading

# GPIO configuration
START_BUTTON_PIN = 23
DEBOUNCE_TIME = 0.2

# Face recognition setup
DATASET_DIR = "Dataset/"
TOLERANCE = 0.6
FACE_RECOGNIZER = None

# MQTT client for deduplication
mqtt_client = None
deduplication_lock = threading.Lock()

def initialize_face_recognition():
    global FACE_RECOGNIZER
    try:
        FACE_RECOGNIZER = FaceRecognizer(
            model_path="haarcascade_frontalface_default.xml", # Assuming you have a pre-trained model here
            min_face_size=100,
            normalize=True,
            radius=30,
            threshold=0.6
        )
        print("Face recognition initialized.")
    except Exception as e:
        print(f"Error initializing face recognition: {e}")
        FACE_RECOGNIZER = None

def initialize_mqtt():
    global mqtt_client
    try:
        mqtt_client = Client("mqtt.example.com", 1883, callback=on_connect)
        mqtt_client.connect("face_recognition")
        mqtt_client.subscribe("face_recognition/log")
    except MQTTException as e:
        print(f"Error connecting to MQTT broker: {e}")
        mqtt_client = None

def on_connect(client, userdata, flags, rc):
    if rc == 0:
        print("Connected with result code "+str(rc))
        initialize_mqtt()

def handle_start_button(button):
    global FACE_RECOGNIZER
    while True:
        try:
            if button.is_pressed():
                if FACE_RECOGNIZER is not None:
                    # Capture video frame
                    with picamera2.PiCamera() as camera:
                        camera.resolution = (640, 480)  # Adjust resolution as needed
                        camera.start_recording('video.h264')
                        frame = camera.read_frame()
                        frame_encoded = encode_image(frame)
                        results = FACE_RECOGNIZER.recognize(frame_encoded)

                        if results:
                            for name, confidence in results.items():
                                if confidence >= TOLERANCE:
                                    if not deduplication_lock.acquire(blocking=False):
                                        continue  # Deduplication logic
                                    print(f"{name} was here")
                                    deduplication_lock.release()
                        else:
                            print("No valid encodings found.")
                            break  # Exit if no faces recognized
                else:
                    print("Face recognition not initialized.")
            time.sleep(DEBOUNCE_TIME)
        except Exception as e:
            print(f"Error processing button: {e}")
            break

def main():
    initialize_face_recognition()
    initialize_mqtt()

    start_button = Button(START_BUTTON_PIN, active_low=False)
    start_button.debounce_time = DEBOUNCE_TIME
    start_button.when_pressed = handle_start_button

    try:
        while True:
            time.sleep(1)  # Polling loop
    except KeyboardInterrupt:
        print("Exiting on user interrupt.")
        # Release resources
        if mqtt_client:
            mqtt_client.disconnect()
        if FACE_RECOGNIZER:
            FACE_RECOGNIZER.destroy()
        picamera2.stop_recording()
        start_button.stop()

if __name__ == "__main__":
    main()

import os
import time
import signal
import logging
from PIL import Image
from PIL import ImageOps
from gpiozero import Display
from paho.mqtt.client import Client, MQTTException

# Initialize logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Define AnimatedGif class
class AnimatedGif:
    def __init__(self, display, folder_path="animations/", width=None, height=None):
        self.display = display
        self.folder_path = folder_path
        self.width = width if width is not None else display.width
        self.height = height if height is not None else display.height
        self.files = []
        self.frames = []
        self.is_running = False
        self.loop_count = 0

    def load_files(self):
        try:
            for file_name in os.listdir(self.folder_path):
                if file_name.endswith(".gif"):
                    file_path = os.path.join(self.folder_path, file_name)
                    if os.path.isfile(file_path):
                        logger.info(f"Loading GIF: {file_name}")
                        self.load_gif(file_path)
                    else:
                        logger.warning(f"File not found: {file_path}")
                else:
                    logger.warning(f"File not a GIF: {file_name}")
        except FileNotFoundError:
            logger.error("No valid GIF files found.")
            raise
        except Exception as e:
            logger.error(f"Error loading GIFs: {e}")

    def load_gif(self, file_path):
        try:
            with Image.open(file_path) as img:
                frames = img.sequence
                if not frames:
                    logger.warning(f"GIF file is not animated: {file_path}")
                    return
                durations = [int(frame.info.get("duration", 0)) for frame in frames]
                self.frames = [ImageOps.fit(frame.resize((self.width, self.height)), (self.width, self.height), Image.ANTIALIAS) for frame in frames]
                self.loop_count = frames[-1].get("loop", 0)
                self.files.append(file_path)
        except (IOError, ValueError) as e:
            logger.error(f"Error processing GIF: {e}")

    def preload(self):
        for file_path in self.files:
            try:
                with Image.open(file_path) as img:
                    frame_duration_ms = durations[0]  # Assuming first frame duration applies to all
                    self.frames = [img.convert("RGB")] * len(self.frames)
                    for i, frame in enumerate(self.frames):
                        frame.putdata(frame.getdata())
                        frame.paste(Image.new("RGB", (self.width, self.height), color=(0, 0, 0)), (0, 0, frame.size))
                        self.frames[i] = self.frames[i].crop((0, 0, self.width, self.height))
            except Exception as e:
                logger.error(f"Error preloading frames: {e}")

    def play(self):
        if not self.files:
            raise FileNotFoundError("No valid GIF files to play.")
        self.is_running = True
        while self.is_running:
            for frame in self.frames:
                self.display.display(frame)
                sleep_time = max(0, int(frame_duration_ms / 1000) - time.monotonic() % int(frame_duration_ms / 1000))
                time.sleep(sleep_time)
                if self.loop_count == 0:
                    self.is_running = False
                else:
                    self.loop_count -= 1
                    if self.loop_count == 0:
                        self.is_running = False
                        break
            if self.is_running:
                return True
        return False

    def run(self):
        while self.is_running:
            self.play()
            time.sleep(0.1)  # Small pause to avoid rapid repeated calls

    def stop(self):
        self.is_running = False
        logger.info("Animation stopped.")

    # Install signal handlers
    @staticmethod
    def signal_handler(signum, frame):
        logger.info("Signal received, stopping animation.")
        # Ensure all files are properly closed
        for file_path in AnimatedGif.files:
            with Image.open(file_path) as img:
                img.close()
        # Stop the running instance if any
        for anim in [g for g in globals().values() if isinstance(g, AnimatedGif) and g.is_running]:
            anim.stop()

    # Register signal handlers for SIGINT and SIGTERM
    signal.signal(signal.SIGINT, AnimatedGif.signal_handler)
    signal.signal(signal.SIGTERM, AnimatedGif.signal_handler)

# Example usage
if __name__ == "__main__":
    display = Display(physical_pin=23)  # Assuming GPIO pin 23 is connected to the display
    anim = AnimatedGif(display, folder_path="animations/")
    anim.load_files()
    anim.preload()
    anim.run()
    anim.stop()

