import time
import logging
import i2c_dev
from i2c_dev import SMBus
from dht import DHT20
from crc import crc8

# Initialize logging
logging.basicConfig(level=logging.INFO, format='[%(levelname)s] %(message)s')

class DHT20Sensor:
    def __init__(self, i2c_bus=1):
        self.i2c_bus = i2c_bus
        self.smbus = SMBus(i2c_bus)
        self.dht20 = None
        self.crc_error_flag = False

        # Wait for power stabilization
        time.sleep(0.5)

        # Attempt to initialize the DHT sensor
        try:
            self.dht20 = DHT20(self.smbus)
            self.dht20.power_on()
            # Check status register
            if self.dht20.read_status() & 0x08 != 0x08:
                logging.error("Status register check failed.")
                return False
        except Exception as e:
            logging.error(f"Error initializing DHT20: {e}")
            return False

    def read_data(self):
        while True:
            try:
                # Poll status until bit 7 clears
                if self.dht20.read_status() & 0x08 == 0:
                    break

                # Retry up to 5 times with 2s delay
                for _ in range(5):
                    time.sleep(2)
                    if self.dht20.read_status() & 0x08 == 0:
                        break

                else:
                    logging.warning("Failed to clear status bit 7 after retries.")
                    return False

            except Exception as e:
                logging.error(f"Error reading from DHT20: {e}")
                return False

        # Read data
        raw_humidity = self.dht20.read_humidity()
        raw_temperature = self.dht20.read_temperature()

        # Compute CRC-8
        crc = crc8(raw_humidity + raw_temperature + b'\x00', polynomial=0x07)
        if crc != raw_humidity[-1]:
            self.crc_error_flag = True

        # Convert raw values to human-readable
        humidity = DHT20.humidity_to_humidity(raw_humidity)
        temperature = DHT20.temperature_to_celsius(raw_temperature)

        return (temperature, humidity, not self.crc_error_flag)

    def close(self):
        self.dht20.power_off()
        self.dht20 = None
        self.smbus.close()

    def __del__(self):
        self.close()

if __name__ == "__main__":
    sensor = DHT20Sensor()
    while True:
        try:
            temp, humidity, crc_error = sensor.read_data()
            if crc_error:
                print(f"Warning: CRC error detected ({hex(crc_error)}). Data may be corrupted.")
            else:
                print(f"Temperature: {temp}°C, Humidity: {humidity}%")
        except Exception as e:
            print(f"Error: {e}")
        time.sleep(10)  # Poll every 10 seconds

import logging
import time
import i2c_dev
from dht import DHT20

# Initialize logging
logging.basicConfig(level=logging.INFO)

class DHT20_I2C:
    def __init__(self):
        try:
            self.bus = i2c_dev.I2C(1)
            self.bus.open()
            logging.info("DHT20 sensor connected to I2C bus 1.")
        except Exception as e:
            logging.error(f"Error connecting to I2C bus 1: {e}")
            self.bus = None
            return

        # Verify sensor
        try:
            self._verify_sensor()
        except Exception as e:
            logging.error(f"Error verifying DHT20 sensor: {e}")
            self.bus.close()
            self.bus = None
            return

    def _verify_sensor(self):
        # Send command to read humidity and temperature
        data = bytearray([0x40, 0x00])  # Start measurement, humidity and temperature
        self.bus.write_bytes(data)

        # Poll status register until measurement is ready or timeout
        start_time = time.time()
        while time.time() - start_time <= 0.1:
            if self.bus.read_byte_data(0x40, 0x00) == 0x00:  # Measurement ready
                break
            time.sleep(0.01)  # Poll roughly every 10 ms

        else:
            logging.error("Timeout waiting for measurement.")
            return

        # Read humidity and temperature data
        humidity_data = self.bus.read_i2c_block_data(0x40, 0x00, 2)
        temperature_data = self.bus.read_i2c_block_data(0x40, 0x01, 2)

        # Compute CRC-8 checksum
        crc = 0xFF
        for byte in bytearray([0x40, 0x00] + humidity_data + temperature_data):
            crc = (crc ^ byte) & 0xFF
            for _ in range(8):
                if crc == 0:
                    break
                crc = (crc >> 1) & 0x01
                crc ^= 0x07 if crc & 0x01 else 0x00

        # Check CRC
        if humidity_data[1] != (crc ^ 0x7F):
            logging.error("CRC error detected.")
            return

        # Extract humidity and temperature
        humidity = (humidity_data[0] << 8) | humidity_data[1]
        temperature = (temperature_data[0] << 8) | temperature_data[1]

        return (temperature, humidity, crc == 0)

    def measure(self):
        return self._verify_sensor()

if __name__ == "__main__":
    dht = DHT20_I2C()
    try:
        temperature, humidity, crc_error = dht.measure()
        if temperature is not None and humidity is not None:
            print(f"Temperature: {temperature} °C, Humidity: {humidity} %, CRC Error: {crc_error}")
        else:
            print("Failed to measure temperature and humidity.")
    except (KeyboardInterrupt, SystemExit):
        logging.info("Closing I2C bus on exit.")
        dht.bus.close()
    except Exception as e:
        logging.error(f"Unexpected error: {e}")

