            yield
        finally:
            self.close()

    def begin(self):
        self.attempts = 0
        while self.attempts < DHT20_MAX_ATTEMPTS:
            try:
                self.i2c.start()
                self.i2c.write(DHT20_ADDRESS, bytearray([DHT20_REGISTER]))
                response = self.i2c.readfrom(DHT20_ADDRESS, 7)
