class PIR_Occupancy_Monitor:
    def __init__(self, mqtt_broker='mqtt.eclipse.org', mqtt_port=1883, mqtt_client_id='pir_monitor'):
        self mqtt_broker = mqtt_broker
        self mqtt_port = mqtt_port
        self mqtt_client_id = mqtt_client_id
        self.sample_events = []
        self.client = None

        try:
            # Initialize GPIO
            GPIO.setup(17, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            self.motion_sensor = MotionSensor(17)

            # Register signal handlers
            self.register_signal_handlers()

        except Exception as e:
            logger.error(f"Initialization failed: {e}")
            self.client = None
            return

    def register_signal_handlers(self):
        def signal_handler(signal, frame):
            logger.info("Exiting gracefully on signal.")
            self.cleanup()
            raise SystemExit(0)

        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

    def poll_sensor(self):
        while True:
            try:
                if self_motion_detected():
                    self.sample_events.append(datetime.now().isoformat())
                    if len(self.sample_events) >= SAMPLE_COUNT:
                        self.log_events()
                    if self.client is not None:
                        self.publish_events()
            except Exception as e:
                logger.error(f"Error during polling: {e}")
                break

    def _motion_detected(self):
        """Check if motion is detected."""
        return not self.motion_sensor.is_active

    def log_events(self):
        """Log the detected events."""
        logger.info(f"Detected events: {self.sample_events}")

    def publish_events(self):
        """Publish detected events to MQTT broker."""
        if self.client is not None:
            try:
                self.client.publish(topic='pir/events', payload=';'.join(self.sample_events))
                logger.info("Events published to MQTT broker.")
            except MQTTException as e:
                logger.error(f"Error publishing events: {e}")

    def cleanup(self):
        """Clean up resources."""
        if self.client is not None:
            self.client.disconnect()
            self.client = None
        GPIO.cleanup()

    def run(self):
        """Start the occupancy monitoring loop."""
        self.poll_sensor()
        logger.info("Occupancy monitoring completed.")

