from typing import Any, Callable, List, Union

class BCMOutputPin(OutputPin):
    def __init__(self, pin_number: int, initial_value: int) -> None:
        if not isinstance(pin_number, int) or pin_number < 0 or pin_number > 31:
            raise ValueError("Pin number must be between 0 and 31.")
        if not isinstance(initial_value, int) or initial_value not in [0, 1]:
            raise ValueError("Initial value must be 0 or 1.")

        try:
            super().__init__(pin_number)
            GPIO.setup(pin_number, GPIO.OUT)
            GPIO.output(pin_number, initial_value)
        except GPIOError as e:
            raise RuntimeError(f"Failed to initialize GPIO: {e}") from e

    def set_value(self, value: int) -> None:
        if value not in [0, 1]:
            raise ValueError("Value must be 0 or 1.")
        try:
            GPIO.output(self._pin, value)
        except GPIOError as e:
            raise RuntimeError(f"Error setting GPIO value: {e}") from e

    def shutdown(self) -> None:
        try:
            GPIO.output(self._pin, GPIO.IN)
            GPIO.cleanup()
        except GPIOError as e:
            raise RuntimeError(f"Error cleaning up GPIO: {e}") from e

if __name__ == '__main__':
    # Demonstration
