DT_PIN = 18   # BCM
PULL_UP resistor = GPIO.PUD_UP
DEBOUNCE_TIME = 0.005  # seconds

class RotaryEncoderError(Exception):
    pass

class RotaryEncoder:
    def __init__(self, callback=None):
        if callable(callback):
            self.callback = callback
        else:
            raise RotaryEncoderError("Provided callback is not callable.")

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(CLK_PIN, GPIO.IN, pull_up_down=resistor)
        GPIO.setup(DT_PIN, GPIO.IN, pull_up_down=resistor)

        self.last_clk_state = None
        self.counter = 0
        self.is_running = False

    def start(self):
        if self.is_running:
            raise ValueError("Encoder is already running.")

        self.is_running = True
        self.thread = threading.Thread(target=self._poll_encoder)
        self.thread.start()

    def stop(self):
        self.is_running = False
        self.thread.join()

    def _poll_encoder(self):
        while self.is_running:
            try:
                clk_state = GPIO.input(CLK_PIN)
                dt_state = GPIO.input(DT_PIN)

                if clk_state != self.last_clk_state:
                    self.last_clk_state = clk_state

                    if dt_state != self.last_dt_state:
                        if clk_state and dt_state == self.last_dt_state:
                            self.counter += 1  # Clockwise
                        elif not clk_state and dt_state != self.last_dt_state:
                            self.counter -= 1  # Counter-clockwise

                        self.last_dt_state = dt_state

                        if self.callback:
                            try:
                                self.callback(self.counter)
                            except Exception as e:
                                print(f"Error in callback: {e}")

                time.sleep(DEBOUNCE_TIME)
            except KeyboardInterrupt:
                self.stop()
                raise

    def cleanup(self):
        GPIO.cleanup()

    def __del__(self):
        self.stop()
        self.cleanup()

