        encoder.start()
        # Simulate user input or other actions here
        # Press Ctrl+C to exit
        signal.pause()
    except KeyboardInterrupt:
        print("Exiting gracefully.")
    finally:
        # Ensure all resources are released on exit
        encoder.cleanup()

