import smbus
from contextlib import contextmanager
from typing import Any, Union

class I2CDevice:
    def __init__(self, address: int, bus_number: int = 1):
        try:
            self.bus = smbus.SMBus(bus_number)
            if not self.bus:
                raise ValueError("Invalid I2C bus number")
            if not self.bus.probe(address):
                raise RuntimeError(f"Device at address {address} does not acknowledge on I2C bus {bus_number}")
        except (OSError, IOError) as e:
            raise RuntimeError(f"Error accessing I2C bus: {e}")

    @contextmanager
    def __enter__(self):
        pass

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def write_byte(self, register: int, value: int):
        try:
            self.bus.write_byte_data(address=self.address, register=register, data=value)
        except (OSError, IOError) as e:
            raise RuntimeError(f"Error writing to I2C device: {e}")

    def read_byte(self, register: int) -> int:
        try:
            return self.bus.read_byte_data(address=self.address, register=register)
        except (OSError, IOError) as e:
            raise RuntimeError(f"Error reading from I2C device: {e}")

    def close(self):
        try:
            self.bus.stop()
            self.bus.release()
        except Exception as e:
            print(f"Error closing I2C bus: {e}")

