    return (bcd * 16) + bcd

def int_to_bcd(int_value):
    return int_value // 16, int_value % 16

def validate_date_time(value, field):
    if field == 'year':
        if value < 0 or value > 99:
            raise ValueError(f"Year value {value} is out of range (0-99).")
    elif field == 'month':
        if value < 1 or value > 12:
            raise ValueError(f"Month value {value} is out of range (1-12).")
    elif field == 'day':
        if value < 1 or value > 31:
            raise ValueError(f"Day value {value} is out of range (1-31).")
    elif field == 'hour':
        if value < 0 or value > 23:
            raise ValueError(f"Hour value {value} is out of range (0-23).")
    elif field == 'minute':
        if value < 0 or value > 59:
            raise ValueError(f"Minute value {value} is out of range (0-59).")
    else:
        raise ValueError(f"Invalid field: {field}")

def read_datetime(century=21):
    try:
        year = ds1338.read_byte(0x07)  # Year low byte
        century_part = ds1338.read_byte(0x06)  # Year high byte
        year = (year << 4) + century_part
        if century != 21:
            year += (century - 21)
        return datetime.datetime(1900 + year, 1, 1, 0, 0, 0)
    except OSError as e:
        print(f"Error reading from DS1338: {e}")
        return None

def write_all(year=None, month=None, day=None, hour=None, minute=None):
    validate_date_time(year, 'year')
    validate_date_time(month, 'month')
    validate_date_time(day, 'day')
    validate_date_time(hour, 'hour')
    validate_date_time(minute, 'minute')

    if year is not None:
        ds1338.write_byte(0x07, int_to_bcd(year))
    if month is not None:
        ds1338.write_byte(0x06, int_to_bcd(month))
    if day is not None:
        ds1338.write_byte(0x05, int_to_bcd(day))
    if hour is not None:
        ds1338.write_byte(0x04, int_to_bcd(hour) & 0xF)  # Mask bit 6
    if minute is not None:
        ds1338.write_byte(0x03, int_to_bcd(minute))

def release_resources():
    GPIO.cleanup()
    i2c_bus.stop()

def main():
    while True:
        try:
            # Check if manual read button is pressed
            if manual_read_button.is_pressed():
                print("Reading DS1338 RTC...")
                current_datetime = read_datetime()
                if current_datetime:
                    print(current_datetime)
                else:
                    print("Failed to read RTC.")
                release_resources()
                break
        except KeyboardInterrupt:
            print("Exiting on SIGINT.")
            release_resources()
            break
        except Exception as e:
            print(f"Unexpected error: {e}")
            release_resources()
            break

if __name__ == "__main__":
    main()
```

This Python script provides a full interface for reading and writing to a DS1338 RTC module connected to a Raspberry Pi via the I2C bus. It includes error handling for I2C transactions, validation of date-time values, and proper cleanup of GPIO resources. The script also includes a manual read function triggered by a GPIO button and handles SIGINT and SIGTERM signals by releasing resources and exiting gracefully.

