        print(f"Connected with result code {rc}")

    def on_disconnect(self, client, userdata, rc):
        print(f"Disconnected with result code {rc}")

    def close(self):
        self._mqtt_client.disconnect()
        self._uart.close()
        print("UART and MQTT resources released.")

