import logging
import serial
import threading
from datetime import datetime
from typing import Dict, Any

# Initialize logging
logging.basicConfig(level=logging.INFO)

class SimpleGPS:
    def __init__(self, port: str = '/dev/serial0', baud_rate: int = 9600):
        self.port = port
        self.baud_rate = baud_rate
        self.connected = False
        self.reader_thread = None
        self.gps_data = None

    def connect(self) -> bool:
        try:
            self.ser = serial.Serial(self.port, self.baud_rate, timeout=1)
            self.connected = True
            logging.info(f"Connected to GPS on {self.port} at {self.baud_rate} baud.")
            return True
        except OSError as e:
            logging.error(f"Error connecting to GPS: {e}")
            return False

    def read_data(self) -> str:
        if not self.connected:
            return None

        data = self.ser.readline().decode('utf-8', errors='ignore').strip()
        if not data:
            self.connected = False
            return None

        return data

    def parse_gga(self, line: str) -> Dict[str, Any] or None:
        try:
            parts = line.split(',')
            utc_time = datetime.fromisoformat(parts[0])
            lat = float(parts[3]) if parts[3] else None
            lon = float(parts[6]) if parts[6] else None
            fix_quality = int(parts[7])
            num_satellites = int(parts[8])

            return {
                'utc_time': utc_time,
                'latitude': lat,
                'longitude': lon,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing GPS data: {e}")
            return None

    def close(self):
        if self.ser:
            self.ser.close()
            self.connected = False
            self.ser = None

    def __del__(self):
        self.close()

if __name__ == "__main__":
    gps = SimpleGPS()

    try:
        gps.connect()
        while True:
            gps_data = gps.read_data()
            if gps_data and gps_data.startswith('$GPGGA'):
                parsed_data = gps.parse_gga(gps_data)
                if parsed_data:
                    logging.info(parsed_data)
            else:
                logging.info("No GPS data available or not a GGA sentence.")

            # Allow graceful shutdown on KeyboardInterrupt
            import sys
            if sys.flags.debug != 2:
                try:
                    import pdb; pdb.set_trace()  # Debugging breakpoint
                except ImportError:
                    pass

            # Check for KeyboardInterrupt
            if gps.connected and (input() or not gps.connected):
                gps.close()
                break

    except KeyboardInterrupt:
        gps.close()
        logging.info("Exiting gracefully.")
