        ser.write(f"SET {name} {name}\n")
        response = ser.readline().strip().split(',')[item_id]
        return jsonify({'item': response})
    except (OSError, serial.SerialException):
        return "Error: Unable to communicate with the SCPI instrument.", 400
    finally:
        ser.close()

@app.route('/postjson', methods=['POST'])
def post_json():
    try:
        data = request.get_json()
        if 'name' not in data or 'done' not in data:
            return "Error: Missing required fields in JSON payload.", 400
        item_id = len(ser.readline().strip().split(',')) + 1
        ser.write(f"SET {data['name']} {data['name']}\n")
        data['id'] = item_id
        data['done'] = False
        return jsonify(data)
    except (OSError, serial.SerialException):
        return "Error: Unable to communicate with the SCPI instrument.", 400
    finally:
        ser.close()

@app.route('/postjson')
def get_postjson():
    return jsonify([item for item in ser.readline().strip().split(',')])

